def semver_sort(versions):
    def parse(v):
        main_build = v.split('+', 1)[0]
        if '-' in main_build:
            main, pre = main_build.split('-', 1)
        else:
            main, pre = main_build, None
        parts = main.split('.')
        major, minor, patch = (int(p) for p in parts[:3])
        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0
            idents = pre.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in idents
            )
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

